--- a/DEV/wad/Pesto-Policy.ps1
+++ b/DEV/wad/Pesto-Policy.ps1
@@ fonction New-PestoCampaignApproval (garde de la jambe de signature)
+function Get-PestoRsaKeyBits {
+    param($Key)
+    if(-not $Key){return 0}
+    # KeySize n'a qu'un accesseur en ecriture sur RSAOpenSsl (fournisseur crypto hors Windows) : le module
+    # exporte est le seul chemin portable. Son sens de lecture depend du fournisseur (CAPI lit a l'envers,
+    # Cng et OpenSSL dans l'ordre) et peut porter un octet de signe en tete : on mesure les bits significatifs
+    # aux deux bouts et on garde le plus grand, un module RSA etant impair avec son bit de poids fort a 1.
+    $modulus=$Key.ExportParameters($false).Modulus
+    if(-not $modulus -or $modulus.Length -eq 0){return 0}
+    $high=$modulus.Length-1
+    while($high -gt 0 -and $modulus[$high] -eq 0){$high--}
+    $low=0
+    while($low -lt $high -and $modulus[$low] -eq 0){$low++}
+    if($high -eq 0 -and $modulus[0] -eq 0){return 0}
+    $head=$modulus[$low];$headBits=0;while($head -gt 0){$headBits++;$head=$head -shr 1}
+    $tail=$modulus[$high];$tailBits=0;while($tail -gt 0){$tailBits++;$tail=$tail -shr 1}
+    $forward=(($modulus.Length-1-$low)*8)+$headBits
+    $reverse=($high*8)+$tailBits
+    if($forward -gt $reverse){return $forward}
+    return $reverse
+}
 function New-PestoCampaignApproval {
-    if(-not $key -or $key.KeySize -lt 2048){throw 'Cle privee RSA 2048 bits minimum requise.'}
+    if(-not $key -or (Get-PestoRsaKeyBits $key) -lt 2048){throw 'Cle privee RSA 2048 bits minimum requise.'}
@@ fonction Assert-PestoCampaignApproval (garde de la jambe de verification)
